env.HH_DENY_HOOK:
// PreToolUse deny list. Grok hooks fail open, so this script must print
// {"decision":"deny","reason":"..."} itself. Paths go through node:path and node:os.
const path = require("node:path");
const os = require("node:os");

const DENY_PHRASES = [
  { phrase: ["git", "push"], reason: "git push is denied" },
  { phrase: ["git", "remote", "add"], reason: "git remote add is denied" },
  { phrase: ["gh", "repo", "create"], reason: "gh repo create is denied" },
  { phrase: ["wrangler", "deploy"], reason: "deploy command is denied" },
  { phrase: ["vercel", "--prod"], reason: "deploy command is denied" },
  { phrase: ["netlify", "deploy"], reason: "deploy command is denied" },
];

const DEPLOY_TOOLS = new Set(["vercel"]);
const DEPLOY_TOOL_WITH_WORD = new Set(["wrangler", "netlify"]);
const GIT_VALUE_FLAGS = new Set([
  "-c",
  "--git-dir",
  "--work-tree",
  "--namespace",
  "--super-prefix",
  "--config-env",
  "--exec-path",
]);
const GH_VALUE_FLAGS = new Set(["--hostname", "--repo", "-r", "--jq", "--template"]);
const DELETE_COMMANDS = new Set(["rm", "rmdir", "rd", "del", "erase", "remove-item", "ri"]);
const READERS = new Set(["cat", "type", "more", "less", "head", "tail", "get-content", "gc", "open"]);
const SHELLS = new Set(["bash", "sh", "zsh", "dash", "pwsh", "powershell", "cmd"]);
const INTRODUCERS = new Set([
  "sudo",
  "command",
  "nohup",
  "nice",
  "npx",
  "bunx",
  "exec",
  "dlx",
  "corepack",
  "env",
  "bash",
  "sh",
  "zsh",
  "dash",
  "pwsh",
  "powershell",
  "cmd",
  "&&",
  "||",
  "|",
  ";",
]);

function say(decision, reason) {
  const payload = reason ? { decision: decision, reason: reason } : { decision: decision };
  process.stdout.write(JSON.stringify(payload));
}

function normCmd(token) {
  let value = String(token).trim();
  if (value.length >= 2) {
    const open = value[0];
    const close = value[value.length - 1];
    if ((open === '"' && close === '"') || (open === "'" && close === "'")) {
      value = value.slice(1, -1).trim();
    }
  }
  const lower = value.toLowerCase();
  if (lower.length === 2 && lower[0] === "/" && lower[1] >= "a" && lower[1] <= "z") return lower;
  const isPath =
    lower.startsWith("/") ||
    lower.startsWith("\\") ||
    lower.includes("\\") ||
    (/^[a-z]:/.test(lower) && (lower[2] === "/" || lower[2] === "\\"));
  let base = lower;
  if (isPath) {
    const slash = Math.max(lower.lastIndexOf("/"), lower.lastIndexOf("\\"));
    if (slash >= 0) base = lower.slice(slash + 1);
  }
  const exts = [".exe", ".cmd", ".bat", ".ps1"];
  for (const ext of exts) {
    if (base.endsWith(ext)) return base.slice(0, -ext.length);
  }
  return base;
}

function toTok(raw) {
  return { raw: raw, cmd: normCmd(raw) };
}

function splitCommand(text) {
  const out = [];
  let current = "";
  let quote = "";
  for (let index = 0; index < text.length; index += 1) {
    const ch = text[index];
    if (quote !== "") {
      if (ch === quote) quote = "";
      else current += ch;
      continue;
    }
    if (ch === "'" || ch === '"') {
      quote = ch;
      continue;
    }
    if (ch === " " || ch === "\t" || ch === "\n" || ch === "\r") {
      if (current.length > 0) {
        out.push(current);
        current = "";
      }
      continue;
    }
    current += ch;
  }
  if (current.length > 0) out.push(current);
  return out;
}

function isShellCommandFlag(cmd) {
  if (cmd === "-c" || cmd === "/c" || cmd === "-command" || cmd === "--command") return true;
  if (cmd.length < 2 || cmd[0] !== "-" || cmd[1] === "-") return false;
  let saw = false;
  for (let index = 1; index < cmd.length; index += 1) {
    const ch = cmd[index];
    if (ch < "a" || ch > "z") return false;
    if (ch === "c") saw = true;
  }
  return saw;
}

function tokenize(argv) {
  const trimmed = argv.map(function (arg) { return String(arg).trim(); }).filter(function (arg) { return arg !== ""; });
  const only = trimmed[0];
  const parts = trimmed.length === 1 && only !== undefined && /\s/.test(only) ? splitCommand(only) : trimmed;
  const out = [];
  let splitNext = false;
  for (const arg of parts) {
    if (splitNext) {
      splitNext = false;
      for (const piece of splitCommand(arg)) {
        if (piece !== "") out.push(toTok(piece));
      }
      continue;
    }
    const tok = toTok(arg);
    out.push(tok);
    const prev = out.length >= 2 ? out[out.length - 2] : undefined;
    if (prev !== undefined && SHELLS.has(prev.cmd) && isShellCommandFlag(tok.cmd)) splitNext = true;
  }
  return out;
}

function isEnvAssignment(raw) {
  return /^[A-Za-z_][A-Za-z0-9_]*=/.test(raw.trim());
}

function isFlag(raw) {
  const value = raw.trim();
  if (value === "--") return true;
  if (value.startsWith("-") && value.length > 1) return true;
  return value.length === 2 && value[0] === "/" && /[a-zA-Z]/.test(value[1]);
}

function isIntroducer(tokens, index) {
  const cmd = tokens[index] && tokens[index].cmd;
  if (cmd === undefined) return false;
  if (INTRODUCERS.has(cmd)) return true;
  if (cmd === "x" || cmd === "-c" || cmd === "/c" || cmd === "-command" || cmd === "--command") {
    const prev = index > 0 ? tokens[index - 1] && tokens[index - 1].cmd : undefined;
    if (cmd === "x") return prev === "npm" || prev === "pnpm" || prev === "yarn" || prev === "bun";
    return prev !== undefined && SHELLS.has(prev);
  }
  return false;
}

function commandIndexes(tokens) {
  const found = [];
  const add = function (start) {
    let cursor = start;
    while (cursor < tokens.length) {
      const tok = tokens[cursor];
      if (tok === undefined) break;
      if (!isEnvAssignment(tok.raw) && !isFlag(tok.raw)) break;
      cursor += 1;
    }
    if (cursor < tokens.length && !found.includes(cursor)) found.push(cursor);
  };
  if (tokens.length > 0) add(0);
  for (let index = 0; index < tokens.length; index += 1) {
    if (isIntroducer(tokens, index)) add(index + 1);
  }
  return found;
}

function startsWithPhrase(tokens, phrase) {
  if (phrase.length === 0 || tokens.length < phrase.length) return false;
  for (let index = 0; index < phrase.length; index += 1) {
    if (tokens[index] !== phrase[index]) return false;
  }
  return true;
}

function reasonForCommand(head, rest) {
  const cmds = [head].concat(rest.map(function (tok) { return tok.cmd; }));
  for (const rule of DENY_PHRASES) {
    if (startsWithPhrase(cmds, rule.phrase)) return rule.reason;
  }
  return null;
}

function skipLeadingFlags(tokens, valueFlags) {
  let index = 0;
  while (index < tokens.length) {
    const tok = tokens[index];
    if (tok === undefined || !isFlag(tok.raw)) break;
    if (tok.cmd === "--") return tokens.slice(index + 1);
    const equals = tok.cmd.indexOf("=");
    const flag = equals >= 0 ? tok.cmd.slice(0, equals) : tok.cmd;
    if (equals < 0 && valueFlags.has(flag)) {
      index += 2;
      continue;
    }
    index += 1;
  }
  return tokens.slice(index);
}

function matchGit(tokens) {
  for (const index of commandIndexes(tokens)) {
    if (!tokens[index] || tokens[index].cmd !== "git") continue;
    const rest = skipLeadingFlags(tokens.slice(index + 1), GIT_VALUE_FLAGS);
    const reason = reasonForCommand("git", rest);
    if (reason !== null) return reason;
  }
  return null;
}

function matchGh(tokens) {
  for (const index of commandIndexes(tokens)) {
    if (!tokens[index] || tokens[index].cmd !== "gh") continue;
    const rest = skipLeadingFlags(tokens.slice(index + 1), GH_VALUE_FLAGS);
    const reason = reasonForCommand("gh", rest);
    if (reason !== null) return reason;
  }
  return null;
}

function isDeployWord(cmd) {
  if (cmd === "deploy") return true;
  return cmd.split(/[^a-z]+/).includes("deploy");
}

function matchDeploy(tokens) {
  let hostinger = false;
  let deployWord = false;
  for (const tok of tokens) {
    if (/\s/.test(tok.raw.trim())) continue;
    const hay = (tok.raw + " " + tok.cmd).toLowerCase();
    if (hay.includes("hostinger")) hostinger = true;
    if (isDeployWord(tok.cmd) || isDeployWord(tok.raw.toLowerCase())) deployWord = true;
  }
  if (hostinger && deployWord) return "deploy command is denied";
  for (const index of commandIndexes(tokens)) {
    const cmd = tokens[index] && tokens[index].cmd;
    if (cmd === undefined) continue;
    const reason = reasonForCommand(cmd, tokens.slice(index + 1));
    if (reason !== null && reason.startsWith("deploy")) return reason;
    if (DEPLOY_TOOLS.has(cmd)) return "deploy command is denied";
    if (!DEPLOY_TOOL_WITH_WORD.has(cmd)) continue;
    for (let cursor = index + 1; cursor < tokens.length; cursor += 1) {
      const later = tokens[cursor];
      if (later !== undefined && !/\s/.test(later.raw.trim()) && isDeployWord(later.cmd)) {
        return "deploy command is denied";
      }
    }
  }
  return null;
}

function stripTrailingSep(value) {
  let end = value.length;
  while (end > 0 && (value[end - 1] === "/" || value[end - 1] === "\\")) end -= 1;
  return value.slice(0, end);
}

function pathKeys(value) {
  const trimmed = String(value).trim();
  const win = stripTrailingSep(path.win32.normalize(trimmed));
  const posix = stripTrailingSep(path.posix.normalize(trimmed.replaceAll("\\", "/")));
  const windowsLike = os.platform() === "win32" || trimmed.includes("\\") || /^[a-zA-Z]:/.test(trimmed);
  if (windowsLike) return [win.toLowerCase(), posix.toLowerCase()];
  return [win, posix];
}

function samePath(left, right) {
  if (String(left).trim() === "" || String(right).trim() === "") return false;
  const rightKeys = new Set(pathKeys(right));
  for (const key of pathKeys(left)) {
    if (key !== "" && rightKeys.has(key)) return true;
  }
  return false;
}

function isFilesystemRoot(operand) {
  const value = String(operand).trim();
  if (value === "") return false;
  let onlySlashes = true;
  for (let index = 0; index < value.length; index += 1) {
    const ch = value[index];
    if (ch !== "/" && ch !== "\\") onlySlashes = false;
  }
  if (onlySlashes) return true;
  if (value.length < 2 || !/^[a-zA-Z]:/.test(value)) return false;
  for (let index = 2; index < value.length; index += 1) {
    const ch = value[index];
    if (ch !== "/" && ch !== "\\") return false;
  }
  return true;
}

function isDot(operand) {
  const value = String(operand).trim();
  return value === "." || value === "./" || value === ".\\" || value === "./." || value === ".\\.";
}

function expandUser(operand) {
  const value = String(operand).trim();
  if (value === "~") return os.homedir();
  if (value.startsWith("~/") || value.startsWith("~\\")) return path.join(os.homedir(), value.slice(2));
  return value;
}

function deleteOperands(tokens) {
  const operands = [];
  for (let index = 0; index < tokens.length; index += 1) {
    const tok = tokens[index];
    if (tok === undefined) break;
    if (tok.cmd === "--") {
      for (const rest of tokens.slice(index + 1)) operands.push(rest.raw);
      break;
    }
    if (isFlag(tok.raw)) continue;
    operands.push(tok.raw);
  }
  return operands;
}

function outsideProject(operand, projectRoot) {
  const expanded = expandUser(operand);
  const abs = path.resolve(projectRoot, expanded);
  if (samePath(abs, projectRoot)) return false;
  const rel = path.relative(projectRoot, abs);
  if (rel === "") return false;
  if (rel.startsWith("..")) return true;
  return path.isAbsolute(rel);
}

function matchDelete(tokens, projectRoot) {
  for (const index of commandIndexes(tokens)) {
    const cmd = tokens[index] && tokens[index].cmd;
    if (cmd === undefined || !DELETE_COMMANDS.has(cmd)) continue;
    for (const operand of deleteOperands(tokens.slice(index + 1))) {
      const expanded = expandUser(operand);
      if (isFilesystemRoot(expanded)) return "deleting a filesystem root is denied";
      if (isDot(operand) || (projectRoot !== "" && samePath(expanded, projectRoot))) {
        return "deleting the project root is denied";
      }
      if (projectRoot !== "" && outsideProject(operand, projectRoot)) {
        return "deleting outside the project is denied";
      }
    }
  }
  return null;
}

function isCredential(filePath) {
  const expanded = expandUser(filePath);
  const norm = String(expanded).replaceAll("\\", "/");
  const base = path.posix.basename(norm).toLowerCase();
  if (base === ".env" || base.startsWith(".env.")) return true;
  if (base.endsWith(".pem")) return true;
  if (base === "credentials.json") return true;
  if (base === "id_rsa" || base === "id_dsa" || base === "id_ecdsa" || base === "id_ed25519") return true;
  const parent = path.posix.basename(path.posix.dirname(norm)).toLowerCase();
  if (base === "config.json" && parent === ".hitchhiker") return true;
  const parts = norm.toLowerCase().split("/");
  for (const part of parts) {
    if (part === ".env") return true;
  }
  return false;
}

function matchRead(tokens) {
  for (const index of commandIndexes(tokens)) {
    const cmd = tokens[index] && tokens[index].cmd;
    if (cmd === undefined || !READERS.has(cmd)) continue;
    for (const operand of deleteOperands(tokens.slice(index + 1))) {
      if (isCredential(operand)) return "reading a credential file is denied";
    }
  }
  return null;
}

function evaluate(argv, projectRoot) {
  const tokens = tokenize(argv);
  if (tokens.length === 0) return { decision: "deny", reason: "empty argv" };
  const git = matchGit(tokens);
  if (git !== null) return { decision: "deny", reason: git };
  const remote = matchGh(tokens);
  if (remote !== null) return { decision: "deny", reason: remote };
  const deploy = matchDeploy(tokens);
  if (deploy !== null) return { decision: "deny", reason: deploy };
  const removed = matchDelete(tokens, projectRoot);
  if (removed !== null) return { decision: "deny", reason: removed };
  const reading = matchRead(tokens);
  if (reading !== null) return { decision: "deny", reason: reading };
  return { decision: "allow", reason: "allowed" };
}

function commandArgv(input) {
  if (Array.isArray(input)) return input.map(String);
  if (typeof input === "string") return [input];
  if (input && typeof input === "object") {
    if (Array.isArray(input.argv)) return input.argv.map(String);
    if (typeof input.command === "string") return [input.command];
    if (Array.isArray(input.command)) return input.command.map(String);
  }
  return [];
}

function collectPaths(input) {
  if (typeof input === "string") return [input];
  if (!input || typeof input !== "object") return [];
  const found = [];
  const keys = ["target_file", "file_path", "filePath", "path", "file"];
  for (const key of keys) {
    const value = input[key];
    if (typeof value === "string" && value.trim() !== "") found.push(value);
    if (Array.isArray(value)) {
      for (const item of value) {
        if (typeof item === "string") found.push(item);
      }
    }
  }
  return found;
}

function decide(event) {
  const tool = String(event.toolName || event.tool_name || "").toLowerCase();
  const input = event.toolInput !== undefined ? event.toolInput : event.tool_input;
  const root = String(event.workspaceRoot || event.workspace_root || event.cwd || "");
  if (tool === "read" || tool === "read_file" || tool === "readfile") {
    for (const file of collectPaths(input)) {
      if (isCredential(file)) return { decision: "deny", reason: "reading a credential file is denied" };
    }
    return { decision: "allow", reason: "allowed" };
  }
  if (
    tool === "bash" ||
    tool === "shell" ||
    tool === "run_terminal_command" ||
    tool === "powershell" ||
    tool === "cmd"
  ) {
    return evaluate(commandArgv(input), root);
  }
  return { decision: "allow", reason: "allowed" };
}

let raw = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", function (chunk) { raw += chunk; });
process.stdin.on("end", function () {
  try {
    const event = raw.trim() === "" ? {} : JSON.parse(raw);
    const result = decide(event);
    say(result.decision, result.reason);
  } catch (error) {
    say("allow", "allowed");
  }
});
